import dis, sys, math
from datetime import datetime
import numpy as np
import pybamm
from pybamm.experiment.step.base_step import BaseStep

TRACKED = {
    'description','direction','duration','is_drive_cycle','is_python_function','period',
    'potential_directions','skip_ok','start_time','tags','temperature','term','term_obj','termination','value'
}
DEF_LINE = BaseStep.__init__.__code__.co_firstlineno

# map offset -> (opname, argval, starts_line)
ins_map = {ins.offset: ins for ins in dis.get_instructions(BaseStep.__init__)}


def run_case(fn):
    pairs = set()
    active = {'enabled': False}
    current_def = {}

    def tracer(frame, event, arg):
        if event == 'call':
            if frame.f_code is BaseStep.__init__.__code__:
                # initialize param defs at function definition line
                for name in frame.f_code.co_varnames[:frame.f_code.co_argcount + frame.f_code.co_kwonlyargcount]:
                    if name in TRACKED:
                        current_def[name] = DEF_LINE
                frame.f_trace_opcodes = True
                active['enabled'] = True
                return tracer
            return None

        if not active['enabled']:
            return tracer

        if frame.f_code is not BaseStep.__init__.__code__:
            return tracer

        if event == 'opcode':
            ins = ins_map.get(frame.f_lasti)
            if ins is None:
                return tracer
            op = ins.opname
            name = ins.argval if isinstance(ins.argval, str) else None
            line = frame.f_lineno
            if name in TRACKED:
                if op == 'STORE_FAST':
                    current_def[name] = line
                elif op == 'LOAD_FAST':
                    d = current_def.get(name)
                    if d is not None:
                        pairs.add((name, d, line))
        elif event == 'return':
            active['enabled'] = False
        return tracer

    sys.settrace(tracer)
    try:
        fn()
    finally:
        sys.settrace(None)
    return pairs


def case01():
    s = pybamm.step.current(1.0, duration='10 seconds', tags='baseline')
    assert math.isclose(s.value, 1.0)

def case02():
    s = pybamm.step.c_rate(0.5, duration='2 minutes', period='5 seconds')
    assert math.isclose(s.value, 0.5)

def case03():
    s = pybamm.step.voltage(4.1, duration='30 seconds', termination='50 mA')
    assert math.isclose(s.value, 4.1)

def case04():
    s = pybamm.step.power(2.5, duration='45 seconds', temperature='25 oC')
    assert math.isclose(s.value, 2.5)

def case05():
    s = pybamm.step.resistance(0.8, duration='1 minute', direction='discharge')
    assert math.isclose(s.value, 0.8)

def case06():
    s = pybamm.step.rest(duration='15 seconds', start_time=datetime(2026,1,1))
    assert s.value == 0

def case07():
    values = np.array([[0.0, 1.0], [2.0, -0.5], [4.0, 0.25]])
    s = pybamm.step.current(values, duration='8 seconds')
    assert s.value.name == 'Drive Cycle'

def case08():
    s = pybamm.step.current(lambda t: 2.0, duration='20 seconds')
    assert s.value == 2.0

def case09():
    s = pybamm.step.current(-1.0, duration='40 seconds', tags=['charge','qa'], skip_ok=False)
    assert s.skip_ok is False

def case10():
    s = pybamm.step.c_rate(-0.25, duration='3 minutes', termination=['4.2 V', '20 mA'], description='qa charge step')
    assert str(s) == 'qa charge step'

cases = [case01,case02,case03,case04,case05,case06,case07,case08,case09,case10]
all_sets = [run_case(c) for c in cases]
inter = set.intersection(*all_sets)

# print sizes and intersection sorted
print('DEF_LINE', DEF_LINE)
print('per-case sizes', [len(s) for s in all_sets])
for item in sorted(inter, key=lambda x: (x[0], x[1], x[2])):
    print(item)
